"Ân cần":["“{Goi} dạo này đẹp quá, {xung} mừng cho {goi}.”","“Nhìn {goi} tươi tắn, {xung} vui lây. Giữ gìn sức khỏe nhé.”","“Hoàng thượng chắc quý {goi} lắm, mong {goi} được yên ổn.”","“Ước gì {xung} có bí quyết như {goi}. Dạy {xung} đi.”","“{Goi} đẹp lên mỗi ngày, ai nhìn cũng thích.”","“Nhớ đừng để người ta ghen, {xung} lo cho {goi}.”","“Sắc mặt {goi} thật tốt. Cứ như vậy nhé.”","“{Xung} thấy {goi} xinh, mà cũng mong {goi} đừng mệt.”","“Chăm sóc nhan sắc cũng vất vả lắm, {goi} nghỉ chút đi.”","“Mong {goi} mãi mãi được như hôm nay.”"],
"Lạnh lùng":["“Đẹp thật. Rồi sao?”","“Hoàng thượng để mắt tới {goi}. Ừ.”","“{Xung} chẳng ngạc nhiên.”","“Dung nhan ấy, ai cũng thấy.”","“Chúc mừng.”","“Có gì đáng nói. {Xung} thấy bình thường.”","“Nhan sắc không giữ được lâu.”","“{Xung} nhìn thấy rồi. Không cần khoe.”","“Hoàng thượng thích thì cứ thích.”","[lo,mid,hi]“Được để mắt thì sao. Sủng ái vốn chẳng bền.”"],
"Nóng nảy":["“Sao {goi} lúc nào cũng được Hoàng thượng để mắt!”","“Đẹp quá nhỉ! Thế còn người khác thì sao!”","“{Xung} ghen đấy, nói thẳng! Bí quyết gì, nói mau!”","“Chẳng công bằng! Cùng vào cung mà {goi} sáng hơn!”","“Hôm nay {goi} làm {xung} tức muốn chết!”","“Ai cho {goi} đẹp thế!”","“Đừng tưởng {xung} không thấy Hoàng thượng nhìn {goi}!”","“Thật chướng mắt! Mà {xung} phải công nhận, đẹp!”","“Dạo này Hoàng thượng chỉ nhắc {goi}! {Xung} nghe phát chán!”","[lo,mid,hi]“Trời ạ, ngay cả Hoàng hậu cũng phải ngoái nhìn {goi}!”"],
"Điềm tĩnh":["“Hoa đẹp tự có người ngắm. {Xung} chỉ đứng nhìn.”","“Ân sủng như nước, chảy đến rồi cũng chảy đi.”","“{Goi} đẹp, {xung} ghi nhận. Thế thôi.”","“Được thương hôm nay, chưa chắc được thương ngày mai.”","“Đẹp là phúc, mà cũng là gánh. {Goi} nhớ.”","“{Xung} chẳng vội, thời gian sẽ phân rõ.”","“Nhan sắc như sương sớm, đẹp mà ngắn.”","“Mỗi người một vận. {Goi} đang gặp vận tốt.”","“Ai rồi cũng có ngày. {Xung} đợi.”","“Không phải ganh, chỉ là thấy rõ.”"],
"Nhiều chuyện":["“{Goi} đẹp thế, chẳng trách có người ngày đêm nhắc đến {goi}.”","“Nghe nói Hoàng thượng hôm qua hỏi han {goi} suốt, thật không?”","“Này, {goi} dùng phấn gì? Mấy tỷ muội đều tò mò.”","“Ai cũng bảo {goi} dạo này khác, chẳng biết có chuyện gì vui.”","“{Xung} nghe cung nữ kể, Hoàng thượng ghé qua cung {goi} đến ba lần!”","“Có người nói {goi} có bí quyết riêng, nói {xung} nghe với!”","“Đẹp thế này, hẳn Thái hậu cũng nghe đồn rồi.”","“Ôi chao, ai cũng đang xầm xì về {goi}, {goi} biết chưa?”","“Cung nhân bảo thái y vừa kê một thang dưỡng nhan cho {goi}, thật hay đùa?”","[lo,mid,hi]“Người ta đồn {goi} đẹp đến mức Hoàng hậu cũng phải để ý, thật không?”"],
"Kín đáo":["“Dạo này {goi} khác lắm. Chắc có chuyện vui.”","“Đẹp… {xung} cũng có mắt.”","“Người ta hay nói, được yêu thì đẹp.”","“{Xung} không nói, nhưng ai cũng đang nghĩ.”","“{Goi} giấu kỹ thật, chẳng nói gì với {xung}.”","“Một chút son, một chút duyên. {Xung} hiểu.”","“Có người nhìn {goi} không phải vô cớ.”","“{Xung} chỉ cười, đừng hỏi vì sao.”","“Hoa đẹp, tất nhiên có ong bướm.”","[lo,mid,hi]“{Goi} tự biết là được, ai đang nhìn {goi} thì đừng nói ra.”"],
"Kiêu ngạo":["“Cũng chỉ hơn người ta chút ít. Đừng tự đắc.”","“Đẹp thì sao, {xung} cũng từng được Hoàng thượng để mắt.”","“{Goi} chưa thấy cảnh {xung} sáng nhất. Thôi, không nói.”","“Nhan sắc thường thôi, chỉ được cái may.”","“Đừng tưởng thế là hơn {xung}.”","“Hứ, ai cũng có ngày được để mắt.”","“{Xung} xuất thân thế nào, {goi} biết chứ?”","“Đẹp một chút mà đã khoe, quê mùa.”","“{Goi} chỉ là hoa nở sớm thôi.”","[lo,mid,hi]“Được khen vài lời mà vênh mặt.”"],
